	page, err := apiclient.GetResourcePage[types.DatabaseServer](ctx, s.cfg.UserClient, &proto.ListResourcesRequest{
		PredicateExpression: fmt.Sprintf(`name == "%s"`, databaseName),
		ResourceType:        types.KindDatabaseServer,
